import {jest} from '@jest/globals';
import {ToolRegistry} from './registry.js';
import {setLogger, type Logger} from '../../shared/logger.js';

describe('ToolRegistry', () => {
  it('throws when registering a tool with an invalid inputSchema', () => {
    const registry = new ToolRegistry();
    const invalidSchema = {
      type: 'object',
      properties: {
        count: {type: 'invalid-type'},
      },
    };

    expect(() => {
      registry.register(
        {
          name: 'invalid_tool',
          description: 'A tool with an invalid schema',
          inputSchema: invalidSchema as any,
        },
        async () => 'result'
      );
    }).toThrow(/invalid_tool/);
  });

  it('throws Unknown tool for an unregistered name', async () => {
    const registry = new ToolRegistry();
    await expect(registry.execute('unregistered', {})).rejects.toThrow(/Unknown tool: unregistered/);
  });

  it('rejects input missing a required property', async () => {
    const registry = new ToolRegistry();
    let called = false;
    registry.register(
      {
        name: 'test_tool',
        description: 'test',
        inputSchema: {
          type: 'object',
          properties: {req: {type: 'string'}},
          required: ['req'],
        },
      },
      async () => {
        called = true;
        return 'ok';
      }
    );

    const response = await registry.execute('test_tool', {});
    expect(response.result).toMatch(/req/);
    expect(called).toBe(false);
  });

  it('passes through extra properties', async () => {
    const registry = new ToolRegistry();
    let capturedInput: any;
    registry.register(
      {
        name: 'test_tool',
        description: 'test',
        inputSchema: {
          type: 'object',
          properties: {req: {type: 'string'}},
        },
      },
      async input => {
        capturedInput = input;
        return 'ok';
      }
    );

    await registry.execute('test_tool', {req: 'val', extra: 'stuff'});
    expect(capturedInput).toEqual({req: 'val', extra: 'stuff'});
  });

  it('rejects wrong-typed fields without leaking values', async () => {
    // ([validated by: Tool Input Validation](../../specs/hal-engine-tool-input-validation/spec.md#validation-at-execute-time))
    const registry = new ToolRegistry();
    registry.register(
      {
        name: 'test_tool',
        description: 'test',
        inputSchema: {
          type: 'object',
          properties: {num: {type: 'number'}},
        },
      },
      async () => 'ok'
    );

    const response = await registry.execute('test_tool', {num: 'not-a-number'});
    expect(response).toMatchObject({
      result: expect.stringMatching(/num.*number/),
    });
    expect(response.result).not.toMatch(/not-a-number/);
  });

  it('redacts property values from rejection results and logs', async () => {
    const registry = new ToolRegistry();
    const SECRET = 'REDACT-ME-123';
    const logs: Record<string, unknown>[] = [];
    const mockLogger: Logger = {
      debug: () => {},
      info: () => {},
      warn: (_category: string, _message: string, fields?: Record<string, unknown>) => {
        if (fields) logs.push(fields);
      },
      error: () => {},
    };
    setLogger(mockLogger);

    try {
      registry.register(
        {
          name: 'test_tool',
          description: 'test',
          inputSchema: {
            type: 'object',
            properties: {
              code: {type: 'string', enum: ['ALLOWED']},
            },
          },
        },
        async () => 'ok'
      );

      const response = await registry.execute('test_tool', {code: SECRET});

      expect({
        result: response.result,
        logs: logs.some(l => JSON.stringify(l).includes(SECRET)),
      }).toEqual({
        result: expect.not.stringMatching(SECRET),
        logs: false,
      });
    } finally {
      setLogger(undefined);
    }
  });

