  const registry = new ToolRegistry();
  const compileSpy = jest.spyOn((registry as any).ajv, 'compile');

  registry.register(
    {
      name: 'test',
      description: 'test',
      inputSchema: {type: 'object', properties: {a: {type: 'string'}}},
    },
    async () => 'ok'
  );

  expect(compileSpy).toHaveBeenCalledTimes(1);

  for (let i = 0; i < 10; i++) {
    await registry.execute('test', {a: 'val'});
