  const registry = new ToolRegistry();
  let schema: Record<string, unknown> = {
    type: 'object',
    properties: {a: {type: 'string'}},
    required: ['a'],
  };

  registry.register(
    () => ({name: 'dynamic', description: 'desc', inputSchema: schema}),
    async () => 'ok'
  );

  // First call with first schema
  const resp1 = await registry.execute('dynamic', {a: 'val'});
  expect({
    result1: resp1.result,
    result2: (await registry.execute('dynamic', {})).result,
  }).toMatchObject({
    result1: 'ok',
    result2: expect.stringMatching(/a/),
  });

  // Change schema
  schema = {
    type: 'object',
    properties: {b: {type: 'string'}},
    required: ['b'],
  };

  const resp3 = await registry.execute('dynamic', {b: 'val'});
  expect({
    result3: resp3.result,
    result4: (await registry.execute('dynamic', {a: 'val'})).result,
  }).toMatchObject({
    result3: 'ok',
    result4: expect.stringMatching(/b/),
  });
});

