  const logs: Record<string, unknown>[] = [];
  const mockLogger: Logger = {
    debug: () => {},
    info: () => {},
    warn: (_category: string, _message: string, fields?: Record<string, unknown>) => {
      if (fields) logs.push(fields);
    },
    error: () => {},
  };
  setLogger(mockLogger);

  try {
    registry.register(
      {
        name: 'test_tool',
