it('re-validates function-valued tool definitions', async () => {
  const registry = new ToolRegistry();
  let schema: any = {
    type: 'object',
    properties: {a: {type: 'string'}},
    required: ['a'],
  };

  registry.register(
    () => ({name: 'dynamic', description: 'desc', inputSchema: schema}),
    async () => 'ok'
  );

  // First call with first schema
  const resp1 = await registry.execute('dynamic', {a: 'val'});
  expect(resp1.result).toBe('ok');

  const resp2 = await registry.execute('dynamic', {});
  expect(resp2.result).toMatch(/a/);

  // Change schema
  schema = {
    type: 'object',
    properties: {b: {type: 'string'}},
    required: ['b'],
  };

  const resp3 = await registry.execute('dynamic', {b: 'val'});
  expect(resp3.result).toBe('ok');

  const resp4 = await registry.execute('dynamic', {a: 'val'});
  expect(resp4.result).toMatch(/b/);
});

